import {pixelToken,cssToken} from './design-tokens.mjs';
/**
 * Vanilla DOM adapter for Keynes-wiki useTheme, useIsMobile and SidebarProvider.
 * Source: HwigwanJi/Keynes-wiki@08959a617056902c2dabd0b1b27b8d6b97b67a7b.
 */
const root=document.documentElement;
const media=matchMedia('(width < '+pixelToken('--ui-mobile-breakpoint',root)+'px)');
const scheme=matchMedia('(prefers-color-scheme: dark)');
const THEME_KEY='keynes-theme', SIDEBAR_KEY='keynes-lab-sidebar',TRADE_SIDEBAR_KEY='keynes-trade-sidebar';
let theme='dark',collapsed=false,tradeCollapsed=true,compactDefault=false,mobileOpen=false;
try{const saved=localStorage.getItem(THEME_KEY);if(['light','dark','system'].includes(saved))theme=saved;collapsed=localStorage.getItem(SIDEBAR_KEY)==='collapsed';tradeCollapsed=localStorage.getItem(TRADE_SIDEBAR_KEY)!=='expanded';}catch{}
const isCollapsed=()=>compactDefault?tradeCollapsed:collapsed;
function toggleSidebar(){if(compactDefault)tradeCollapsed=!tradeCollapsed;else collapsed=!collapsed;try{localStorage.setItem(compactDefault?TRADE_SIDEBAR_KEY:SIDEBAR_KEY,isCollapsed()?'collapsed':'expanded');}catch{}paint();}
const icons={system:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',light:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',dark:'<path d="M20.8 13.1A9 9 0 0 1 10.9 3.2 9 9 0 1 0 20.8 13.1Z"/>'};
const svg=path=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+path+'</svg>';
function paint(){const compact=isCollapsed();root.dataset.theme=theme==='system'?(scheme.matches?'dark':'light'):theme;const themeColor=document.querySelector('meta[name="theme-color"]');if(themeColor)themeColor.content=cssToken('--ds-bg-canvas',root);root.dataset.sidebarState=compact?'collapsed':'expanded';const button=document.querySelector('[data-shell="theme"]');if(button){button.innerHTML=svg(icons[theme]);const label={system:'시스템 설정',light:'라이트',dark:'다크'}[theme];button.title='테마: '+label;button.setAttribute('aria-label','테마: '+label+' · 누르면 변경');}const collapse=document.querySelector('[data-shell="collapse"]');if(collapse){collapse.setAttribute('aria-expanded',String(!compact));collapse.setAttribute('aria-label',compact?'사이드바 펼치기':'사이드바 접기');collapse.title=(compact?'사이드바 펼치기':'사이드바 접기')+' (Ctrl/⌘ B)';}}
function syncMobile({focus=false}={}){const shell=document.querySelector('.shell'),sidebar=document.querySelector('.sidebar'),main=document.querySelector('.main');if(!shell||!sidebar||!main)return;const open=media.matches&&mobileOpen;shell.classList.toggle('menu-open',open);main.inert=open;document.body.style.overflow=open?'hidden':'';sidebar.id='main-sidebar';sidebar.inert=media.matches&&!open;sidebar.setAttribute('aria-label','주요 메뉴');if(open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');}else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');}document.querySelectorAll('[data-shell="mobile"]').forEach(b=>{b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-controls','main-sidebar');});if(focus&&open)sidebar.querySelector('[data-shell="close"]')?.focus();}
export function closeSidebar({restoreFocus=false}={}){mobileOpen=false;syncMobile();if(restoreFocus)document.querySelector('[data-shell="mobile"]')?.focus();}
export function mountShell(options={}){compactDefault=options.compactDefault===true;paint();syncMobile();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-shell]');if(!button)return;switch(button.dataset.shell){case'theme':theme=({system:'light',light:'dark',dark:'system'})[theme];try{localStorage.setItem(THEME_KEY,theme);}catch{}paint();break;case'collapse':toggleSidebar();break;case'mobile':mobileOpen=!mobileOpen;syncMobile({focus:true});break;case'close':closeSidebar({restoreFocus:true});break;}});
document.addEventListener('keydown',event=>{if(event.isComposing||event.keyCode===229)return;if(event.code==='KeyB'&&(event.metaKey||event.ctrlKey)&&!event.target.closest('input,textarea,select,[contenteditable="true"]')&&!document.querySelector('dialog[open]')){event.preventDefault();if(media.matches){mobileOpen=!mobileOpen;syncMobile({focus:true});}else toggleSidebar();return;}if(!media.matches||!mobileOpen)return;if(event.key==='Escape'){event.preventDefault();closeSidebar({restoreFocus:true});return;}if(event.key==='Tab'){const controls=[...document.querySelector('.sidebar').querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
media.addEventListener('change',()=>{mobileOpen=false;syncMobile();});
scheme.addEventListener('change',()=>{if(theme==='system')paint();});
window.addEventListener('storage',event=>{if(event.key===THEME_KEY){theme=['light','dark','system'].includes(event.newValue)?event.newValue:'dark';paint();}});

